import { DatabaseSync } from 'node:sqlite';
import { readFileSync } from 'node:fs';
const cases = JSON.parse(readFileSync('tests/sql-fixtures.json','utf8')).cases;
const migration = readFileSync('sql/001_initial.sql','utf8');
const connection = readFileSync('sql/connection.sql','utf8');
function rows(db, sql, params=[]) { return db.prepare(sql).all(...params).map(Object.values); }
function snapshot(db) { return rows(db,"SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").map(([name])=>[name, rows(db, 'SELECT * FROM "'+name.replaceAll('"','""')+'" ORDER BY rowid')]); }
let rejects=0;
for (const c of cases) {
 const db = new DatabaseSync(':memory:', {allowExtension:false});
 try {
  db.exec(connection); db.exec(migration);
  for (const step of [...c.setup,...c.steps]) {
   const deny = step.expectRejected === true || step.expectError !== undefined;
   const before = deny ? JSON.stringify(snapshot(db)) : null;
   db.exec('SAVEPOINT node_fixture');
   let result, rejected;
   try { result = rows(db,step.sql,step.params??[]); } catch (e) { rejected=e; }
   if (rejected) {
    if (!deny || (rejected.errcode & 255)!==19) throw new Error(c.id+': unexpected failure '+rejected.message);
    if (before!==JSON.stringify(snapshot(db))) throw new Error(c.id+': rejected operation changed rows');
    if (step.expectError!==undefined && !rejected.message.includes(step.expectError)) throw new Error(c.id+': missing normative error code');
    rejects++; db.exec('ROLLBACK TO node_fixture');
   } else {
    if (deny) throw new Error(c.id+': negative accepted');
    if (step.expectRows!==undefined && JSON.stringify(result)!==JSON.stringify(step.expectRows)) throw new Error(c.id+': row assertion mismatch');
   }
   db.exec('RELEASE node_fixture');
  }
  if (rows(db,'PRAGMA foreign_key_check').length!==0 || JSON.stringify(rows(db,'PRAGMA integrity_check'))!=='[["ok"]]') throw new Error(c.id+': integrity failure');
 } finally { db.close(); }
}
const v = new DatabaseSync(':memory:');
console.log(JSON.stringify({scope:'Node24 built-in driver, in-memory logical SQL fixtures only; not WAL or product execution',node:process.version,sqlite:rows(v,'select sqlite_version()')[0][0],cases:cases.length,negativeRejections:rejects,productTestsExecuted:0})); v.close();
